const item = $input.first().json;
const errors = [];

const matiere = item['Matière'] || item['Matiere'] || '';
const niveau = item['Niveau'] || '';
const notion = item['Notion / Chapitre'] || item['Notion'] || '';
const profNom = item['Nom du professeur'] || '';
const profEmail = item['Email du professeur - pour validation des cartes']
  || item['Email du professeur']
  || item['Votre email - pour votre validation finale des cartes créées']
  || item['Votre email - pour votre validation finale des cartes creees']
  || '';
const nbCartes = parseInt(
  item['Nombre de cartes souhaite']
  || item['Nombre de cartes souhaité']
  || '15'
) || 15;
const instructions = item['Instructions supplémentaires pour la création des cartes']
  || item['Instructions supplementaires']
  || '';

const fichierUrl = item['Le fichier pdf contenant les notions importantes']
  || item['Joindre le fichier pdf contenant les notions importantes']
  || item['Fichier PDF']
  || '';

if (!matiere) errors.push('Matiere manquante');
if (!niveau) errors.push('Niveau manquant');
if (!notion) errors.push('Notion manquante');
if (!profEmail || !profEmail.includes('@')) errors.push('Email invalide');
if (!fichierUrl) errors.push('Fichier PDF manquant');

let fileId = '';
const match = fichierUrl.match(/[-\w]{25,}/);
if (match) fileId = match[0];
else if (fichierUrl) errors.push("Impossible d'extraire l'ID du fichier");

const id = 'box_' + Math.random().toString(36).substring(2, 10);
const codeSup = 'SUP-' + Math.random().toString(36).substring(2, 10).toUpperCase();

return [{
  json: {
    valid: errors.length === 0,
    errors: errors.join(', '),
    matiere: matiere.trim(),
    niveau: niveau.trim(),
    notion: notion.trim(),
    prof_nom: profNom.trim(),
    prof_email: profEmail.trim(),
    nb_cartes: nbCartes,
    instructions: instructions.trim(),
    source_file_id: fileId,
    id: id,
    code_suppression: codeSup,
    date_creation: new Date().toISOString().split('T')[0],
    row_number: item.row_number || item['row_number'] || 0
  }
}];

const prevData = $('Valider entree').first().json;
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64Pdf = binaryData.toString('base64');

// Construire le prompt
const prompt = `Tu es un assistant pedagogique pour un college francais. Tu crees des fiches de revision (flashcards) au format question/reponse a partir du contenu d'un cours.

CONTEXTE :
- Matiere : ${prevData.matiere}
- Niveau : ${prevData.niveau}
- Notion/Chapitre : ${prevData.notion}
- Nombre de cartes demande : ${prevData.nb_cartes}
${prevData.instructions ? '- Instructions du professeur : ' + prevData.instructions : ''}

CONSIGNES :
1. Genere exactement ${prevData.nb_cartes} flashcards question/reponse.
2. Les questions doivent couvrir les points essentiels : definitions, mecanismes, dates, formules, exemples.
3. Les reponses doivent etre CONCISES (2-3 phrases maximum) mais COMPLETES et EXACTES.
4. Adapte le vocabulaire au niveau ${prevData.niveau} (college francais).
5. Varie les types de questions : "Qu'est-ce que...", "Comment...", "Pourquoi...", "Cite...", "Quelle est la difference entre...".
6. Attribue un niveau de difficulte a chaque carte : "facile", "moyen", ou "difficile".
7. Ne modifie PAS les informations du cours.

IMPORTANT : Reponds UNIQUEMENT avec un JSON valide, sans texte avant ni apres :
{
  "cartes": [
    { "numero": 1, "question": "...", "reponse": "...", "difficulte": "facile" }
  ],
  "notes": "Commentaire optionnel si contenu insuffisant"
}`;

// Corps de la requete Claude avec PDF en base64
const requestBody = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 4096,
  messages: [{
    role: 'user',
    content: [
      {
        type: 'document',
        source: {
          type: 'base64',
          media_type: 'application/pdf',
          data: base64Pdf
        }
      },
      {
        type: 'text',
        text: prompt
      }
    ]
  }]
};

return [{
  json: {
    requestBody: requestBody,
    ...prevData
  }
}];

const prevData = $('Preparer requete Claude').first().json;
const claudeResponse = $input.first().json;

let content = '';
if (claudeResponse.content && claudeResponse.content[0]) {
  content = claudeResponse.content[0].text || '';
}

let parsed;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Pas de JSON dans la reponse');
  }
} catch (e) {
  return [{
    json: {
      parse_ok: false,
      error: 'Erreur de parsing : ' + e.message,
      ...prevData
    }
  }];
}

const cartes = parsed.cartes || [];
if (cartes.length === 0) {
  return [{
    json: {
      parse_ok: false,
      error: 'Aucune carte generee',
      ...prevData
    }
  }];
}

// Construire le fichier flashcard complet
const flashcardFile = {
  id: prevData.id,
  matiere: prevData.matiere,
  niveau: prevData.niveau,
  notion: prevData.notion,
  prof_nom: prevData.prof_nom,
  prof_email: prevData.prof_email,
  code_suppression: prevData.code_suppression,
  date_creation: prevData.date_creation,
  nb_cartes: cartes.length,
  source_filename: 'upload.pdf',
  cartes: cartes
};

// Preparer en binaire pour upload Drive
const jsonStr = JSON.stringify(flashcardFile, null, 2);
const buffer = Buffer.from(jsonStr, 'utf-8');

return [{
  json: {
    parse_ok: true,
    nb_cartes_generees: cartes.length,
    notes: parsed.notes || '',
    flashcard_file: flashcardFile,
    ...prevData
  },
  binary: {
    data: await this.helpers.prepareBinaryData(buffer, prevData.id + '.json', 'application/json')
  }
}];

const prevData = $('Parser reponse Claude').first().json;
const uploadResult = $('Upload Flashcards').first().json;
const driveFileId = uploadResult.id || uploadResult.fileId || '';
const code = prevData.code_suppression;

// Construire l'apercu des cartes (max 5 en preview)
const cartes = prevData.flashcard_file.cartes || [];
const maxPreview = Math.min(cartes.length, 5);
let cartesHtml = '';
for (let i = 0; i < maxPreview; i++) {
  const c = cartes[i];
  const diff = c.difficulte === 'facile' ? '#16a34a' : c.difficulte === 'moyen' ? '#d97706' : '#dc2626';
  cartesHtml += `<div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:8px;padding:12px;margin:8px 0">
    <div style="color:${diff};font-size:12px;font-weight:bold;margin-bottom:4px">${c.difficulte.toUpperCase()}</div>
    <div style="font-weight:bold;margin-bottom:6px">Q${c.numero}: ${c.question}</div>
    <div style="color:#475569">${c.reponse}</div>
  </div>`;
}
if (cartes.length > maxPreview) {
  cartesHtml += `<p style="color:#64748b;text-align:center">... et ${cartes.length - maxPreview} autres cartes</p>`;
}

const baseUrl = 'https://n8n.srv868991.hstgr.cloud/webhook';
const selectUrl = `${baseUrl}/box-select?file_id=${driveFileId}&code=${encodeURIComponent(code)}`;

const emailHtml = `<h2>BOX - Fiches a valider</h2>
<p><strong>Matiere :</strong> ${prevData.matiere}<br>
<strong>Niveau :</strong> ${prevData.niveau}<br>
<strong>Notion :</strong> ${prevData.notion}<br>
<strong>Nombre de cartes :</strong> ${cartes.length}</p>
<hr>
<h3>Apercu des cartes generees :</h3>
${cartesHtml}
<hr>
<p style="text-align:center;margin:24px 0">
  <a href="${selectUrl}" style="background:#2563eb;color:white;padding:14px 32px;border-radius:8px;text-decoration:none;font-size:16px;font-weight:bold">&#128203; Relire et choisir les cartes</a>
</p>
<p style="color:#64748b;font-size:12px;text-align:center">Vous pourrez decocher les cartes a exclure avant publication.<br>
Les fiches selectionnees seront accessibles aux eleves sur <a href="https://ericduchateau.github.io/box/">la page BOX</a>.<br>
Code de suppression (a conserver) : <code>${prevData.id}</code> / <code>${code}</code></p>`;

return [{ json: {
  prof_email: prevData.prof_email,
  notion: prevData.notion,
  email_html: emailHtml
} }];
